function relu(x) { return x.map(v => Math.max(0, v)); }

function softmax(x) {
  const max = Math.max(...x);
  const exp = x.map(v => Math.exp(v - max));
  const sum = exp.reduce((a,b) => a+b, 0);
  return exp.map(v => v/sum);
}

function matVec(W, x, b) {
  return b.map((bi, i) => bi + W[i].reduce((s, wij, j) => s + wij * x[j], 0));
  // W is [out x in], b is [out]
}

// Normalize landmarks same way as training
function normalizeLandmarks(landmarks) {
  // landmarks: array of 21 [x,y,z]
  const wrist = landmarks[0];
  let pts = landmarks.map(p => [p[0]-wrist[0], p[1]-wrist[1], p[2]-wrist[2]]);
  let maxVal = 0;
  for (const p of pts) for (const v of p) if (Math.abs(v) > maxVal) maxVal = Math.abs(v);
  if (maxVal < 1e-6) maxVal = 1e-6;
  pts = pts.map(p => p.map(v => v/maxVal));
  return pts.flat();
}

function predictSign(landmarks) {
  // landmarks: array of 21 {x,y,z} objects (from MediaPipe)
  const pts = landmarks.map(l => [l.x, l.y, l.z]);
  let x = normalizeLandmarks(pts);

  for (let i = 0; i < SIGN_MODEL.layers.length; i++) {
    const layer = SIGN_MODEL.layers[i];
    // W stored as [in x out], need to transpose
    const W_T = layer.W; // shape [in x out]
    const out = layer.b.map((bi, j) => {
      return bi + x.reduce((s, xi, k) => s + W_T[k][j] * xi, 0);
    });
    x = i < SIGN_MODEL.layers.length - 1 ? relu(out) : softmax(out);
  }

  const maxIdx = x.indexOf(Math.max(...x));
  return {
    label: SIGN_MODEL.classes[maxIdx],
    confidence: x[maxIdx],
    probs: x
  };
}
